1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects references clients (FK); H2 refuses to TRUNCATE an FK-referenced table, so lift
36	        // referential integrity for the duration of the reset.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        try {
39	            jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
40	            jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
41	            jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
42	            jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
43	            jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
44	            jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
45	        } finally {
46	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
47	        }
48	    }
49	
50	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
51	    @SuppressWarnings("unchecked")
52	    @PostMapping("/seed")
53	    public void seed(@RequestBody Map<String, Object> fixture) {
54	        List<Map<String, Object>> clients =
55	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
56	        for (Map<String, Object> c : clients) {
57	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
58	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
59	        }
60	        List<Map<String, Object>> projects =
61	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
62	        for (Map<String, Object> p : projects) {
63	            jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
64	                    ((Number) p.get("id")).longValue(), p.get("name"),
65	                    ((Number) p.get("clientId")).longValue());
66	        }
67	        List<Map<String, Object>> contacts =
68	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
69	        for (Map<String, Object> ct : contacts) {
70	            jdbc.update(
71	                    "INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
72	                    ((Number) ct.get("id")).longValue(),
73	                    ((Number) ct.get("clientId")).longValue(),
74	                    ct.get("name"), ct.get("email"), ct.get("role"));
75	        }
76	        List<Map<String, Object>> tasks =
77	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
78	        for (Map<String, Object> t : tasks) {
79	            Object done = t.get("done");
80	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
81	                    ((Number) t.get("id")).longValue(),
82	                    ((Number) t.get("projectId")).longValue(),
83	                    t.get("title"),
84	                    done != null && Boolean.parseBoolean(done.toString()));
85	        }
86	        List<Map<String, Object>> invoices =
87	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
88	        for (Map<String, Object> inv : invoices) {
89	            Object status = inv.get("status");
90	            Object issuedDate = inv.get("issuedDate");
91	            Object dueDate = inv.get("dueDate");
92	            // Amount is derived from the invoice's line items (V13), so it is not seeded directly;
93	            // the column defaults to 0.
94	            jdbc.update(
95	                    "INSERT INTO invoices (id, project_id, status, issued_date, due_date)"
96	                            + " VALUES (?, ?, ?, ?, ?)",
97	                    ((Number) inv.get("id")).longValue(),
98	                    ((Number) inv.get("projectId")).longValue(),
99	                    status == null ? "DRAFT" : status.toString(),
100	                    issuedDate == null ? null : java.sql.Date.valueOf(issuedDate.toString()),
101	                    dueDate == null ? null : java.sql.Date.valueOf(dueDate.toString()));
102	            List<Map<String, Object>> lineItems =
103	                    (List<Map<String, Object>>) inv.getOrDefault("lineItems", List.of());
104	            for (Map<String, Object> li : lineItems) {
